{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-web-prototype-taste-editorial",
  "title": "Web Prototype Taste Editorial",
  "title_i18n": {
    "zh-CN": "Web Prototype Taste 编辑风格",
    "zh-TW": "Web Prototype Taste 編輯風格",
    "ja": "Web Prototype Taste エディトリアル",
    "ko": "Web Prototype Taste 에디토리얼",
    "de": "Web Prototype Taste Editorial",
    "fr": "Web Prototype Taste Editorial",
    "ru": "Web Prototype Taste Editorial",
    "es": "Web Prototype Taste Editorial",
    "pt-BR": "Web Prototype Taste Editorial",
    "it": "Web Prototype Taste Editorial",
    "vi": "Web Prototype Taste Editorial",
    "pl": "Web Prototype Taste Editorial",
    "id": "Web Prototype Taste Editorial",
    "nl": "Web Prototype Taste Editorial",
    "ar": "Web Prototype Taste Editorial",
    "tr": "Web Prototype Taste Editorial",
    "uk": "Web Prototype Taste Editorial",
    "en": "Web Prototype Taste Editorial"
  },
  "version": "0.1.0",
  "description": "Editorial-minimalist web prototype. Warm monochrome canvas, serif display + grotesque body, 1px hairline borders, muted pastel chips, generous macro-whitespace, ambient micro-motion. Distilled from Leonxlnx/taste-skill `minimalist-skill`.",
  "description_i18n": {
    "zh-CN": "极简编辑风格网页原型。暖色单色调画布，衬线标题配无衬线正文，1px 细线边框，柔和粉彩色块，大量留白，微妙动效。",
    "zh-TW": "極簡編輯風格網頁原型。暖色單色調畫布，襯線標題配無襯線內文，1px 細線邊框，柔和粉彩色塊，大量留白，微妙動效。",
    "ja": "エディトリアル・ミニマリストなウェブプロトタイプ。暖色モノクロームキャンバス、セリフ見出し＋グロテスク本文、1pxヘアライン、ミュートパステルチップ、余白重視、アンビエントモーション。",
    "ko": "에디토리얼 미니멀리스트 웹 프로토타입. 따뜻한 단색 캔버스, 세리프 헤딩 + 그로테스크 본문, 1px 헤어라인 테두리, 뮤티드 파스텔 칩, 넉넉한 여백, 은은한 마이크로 모션.",
    "de": "Editorial-minimalistischer Web-Prototyp. Warme monochrome Leinwand, Serifenschrift für Überschriften + groteske Schrift für Text, 1px Haarlinien, gedämpfte Pastellfarben, großzügiger Weißraum, subtile Mikroanimationen.",
    "fr": "Prototype web éditorial-minimaliste. Toile monochrome chaleureuse, titre serif + corps grotesque, bordures 1px, pastels atténués, espaces blancs généreux, micro-mouvements ambiants.",
    "ru": "Редакционно-минималистичный веб-прототип. Тёплый монохромный холст, засечки в заголовках + гротеск в тексте, контуры 1px, приглушённые пастельные чипы, щедрые отступы, микроанимации.",
    "es": "Prototipo web editorial-minimalista. Lienzo monocromático cálido, título serif + cuerpo grotesco, bordes de 1px, chips pastel tenues, espacios en blanco generosos, micro-movimiento ambiental.",
    "pt-BR": "Protótipo web editorial-minimalista. Canvas monocromático quente, título serifado + corpo grotesco, bordas de 1px, chips pastéis suaves, espaços em branco generosos, micro-movimento ambiente.",
    "it": "Prototipo web editoriale-minimalista. Tela monocromatica calda, titoli serif + corpo grottesco, bordi 1px, chip pastello tenue, ampi spazi bianchi, micro-movimento ambientale.",
    "vi": "Nguyên mẫu web biên tập tối giản. Canvas đơn sắc ấm áp, tiêu đề serif + nội dung grotesque, viền 1px, màu pastel nhẹ nhàng, khoảng trắng rộng rãi, chuyển động vi mô.",
    "pl": "Edytorsko-minimalistyczny prototyp strony. Ciepłe monochromatyczne płótno, nagłówki szeryfowe + groteskowa treść, obramowania 1px, stonowane pastele, obszerne białe przestrzenie, mikro-animacje.",
    "id": "Prototipe web editorial-minimalis. Kanvas monokrom hangat, judul serif + bodi grotesque, garis 1px, chip pastel lembut, ruang putih luas, gerakan mikro halus.",
    "nl": "Redactioneel-minimalistisch webprototype. Warm monochroom canvas, serif titels + grotesk body, 1px haarlijnen, gedempte pastelchips, royale witruimte, subtiele micro-bewegingen.",
    "ar": "نموذج ويب تحريري مبسط. لوحة أحادية اللون دافئة، عناوين serif + نص grotesque، حدود 1px، رقائق باستيل هادئة، مساحات بيضاء واسعة، حركات دقيقة محيطة.",
    "tr": "Editoryal-minimalist web prototipi. Sıcak monokrom tuval, serif başlık + grotesk gövde, 1px ince kenarlıklar, pastel tonlar, bol beyaz alan, ortam mikro-hareketi.",
    "uk": "Редакційно-мінімалістичний веб-прототип. Теплий монохромний полотно, заголовки з засічками + гротеск у тексті, межі 1px, приглушені пастельні чипи, щедрі відступи, мікроанімації.",
    "en": "Editorial-minimalist web prototype. Warm monochrome canvas, serif display + grotesque body, 1px hairline borders, muted pastel chips, generous macro-whitespace, ambient micro-motion. Distilled from Leonxlnx/taste-skill `minimalist-skill`."
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/web-prototype-taste-editorial",
  "tags": [
    "example",
    "first-party",
    "prototype",
    "design",
    "web"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "prototype",
    "scenario": "design",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Editorial-minimalist web prototype. Warm monochrome canvas, serif display + grotesque body, 1px hairline borders, muted pastel chips, generous macro-whitespace, ambient micro-motion. Distilled from Leonxlnx/taste-skill `minimalist-skill`.",
        "zh-CN": "使用这个插件完成以下任务：Editorial-minimalist web prototype. Warm monochrome canvas, serif display + grotesque body, 1px hairline borders, muted pastel chips, generous macro-whitespace, ambient micro-motion. Distilled from Leonxlnx/taste-skill `minimalist-skill`."
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Web Prototype Taste Editorial"
        }
      ]
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "designSystem": {
        "primary": true
      },
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
